    @Test @Order(3) void tc06_30_31_32_33_34_36_businessOutboxUsesRealSmtpAndStopsAfterPayment()throws Exception{
        Object clock=ReflectionTestUtils.getField(BusinessTime.class,"clock");LocalDate due=f.db.sql("SELECT due_date FROM invoices WHERE id=:id").param("id",invoice).query(LocalDate.class).single();LocalDateTime at=due.plusDays(2).atTime(12,0);ReflectionTestUtils.setField(BusinessTime.class,"clock",Clock.fixed(at.atZone(BusinessTime.ZONE).toInstant(),BusinessTime.ZONE));
        try{assertThat(call("TENANT","GET","/tenant/invoices/"+invoice,null,200).path("status").asText()).isEqualTo("OVERDUE");jobs.scan(at);jobs.deliver(at);for(int i=0;i<5;i++)worker.runBatch(at);long sent=count("SELECT COUNT(*) FROM communication_deliveries d JOIN communication_rules r ON r.id=d.rule_id WHERE d.source_id="+invoice+" AND d.channel='EMAIL' AND r.event_type='INVOICE_OVERDUE' AND d.status='SENT' AND d.result_code='SMTP_ACCEPTED'");assertThat(sent).isEqualTo(1);String body=f.db.sql("SELECT d.body FROM communication_deliveries d JOIN communication_rules r ON r.id=d.rule_id WHERE d.source_id=:id AND d.channel='EMAIL' AND r.event_type='INVOICE_OVERDUE'").param("id",invoice).query(String.class).single();assertThat(body).contains("4200000");assertThat(count("SELECT COUNT(*) FROM notifications WHERE user_id=5 AND reference_type='INVOICE' AND reference_id="+invoice)).isPositive();long emailCount=count("SELECT COUNT(*) FROM communication_deliveries WHERE channel='EMAIL' AND status='SENT'");jobs.scan(at);for(int i=0;i<3;i++)worker.runBatch(at);assertThat(count("SELECT COUNT(*) FROM communication_deliveries WHERE channel='EMAIL' AND status='SENT'")).isEqualTo(emailCount);
            long version=f.db.sql("SELECT version FROM invoices WHERE id=:id").param("id",invoice).query(Long.class).single();call("OWNER","POST","/admin/invoices/"+invoice+"/payments",Map.of("amount",4200000,"paymentMethod","CASH","paidAt",at.minusSeconds(1).toString(),"note","TEST full receipt after due","version",version),200);jobs.scan(at.plusDays(1));for(int i=0;i<3;i++)worker.runBatch(at.plusDays(1));assertThat(count("SELECT COUNT(*) FROM communication_deliveries d JOIN communication_rules r ON r.id=d.rule_id WHERE d.source_id="+invoice+" AND d.channel='EMAIL' AND r.event_type='INVOICE_OVERDUE' AND d.status='SENT'")).isEqualTo(sent);
            assertThat(count("SELECT COUNT(*) FROM communication_deliveries WHERE channel='ZALO' AND status IN ('SENT','DELIVERED')")).isZero();
        }finally{ReflectionTestUtils.setField(BusinessTime.class,"clock",clock);}
    }
